drawCombatBolts();for(const effect of effects){const a=effect.life/effect.max;if(effect.kind==='soul'){g.save();g.globalAlpha=Math.min(1,a*2);const h=(effect.size===30?88:47)*(1+(1-a)*.15),x=effect.x+Math.sin((1-a)*8)*7,y=effect.y-(1-a)*85;g.drawImage(combatVfx,120,45,550,800,x-h*.344,y-h*.6,h*.688,h);g.restore();}else if(effect.kind==='ice-shatter'){drawIceShatter(effect);}else if(effect.kind==='muzzle'){g.save();g.globalAlpha=a;g.strokeStyle='#fff1b0';g.lineWidth=3;g.beginPath();g.moveTo(effect.x-8,effect.y);g.lineTo(effect.x+8,effect.y);g.moveTo(effect.x,effect.y-8);g.lineTo(effect.x,effect.y+8);g.stroke();g.restore();}else if(effect.kind==='heal-ray'){drawHealFlower(effect);}else if(effect.kind==='enemy-strike'){drawEnemyStrike(effect);}else if(effect.kind==='blast'){g.save();g.globalAlpha=a;g.strokeStyle='#ffe87a';g.lineWidth=4;g.fillStyle='#ffca4b70';g.shadowColor='#ffd744';g.shadowBlur=reducedMotion()?0:16;g.beginPath();g.arc(effect.x,effect.y,effect.radius*(1-a),0,Math.PI*2);g.fill();g.stroke();for(let i=0;i<10;i++){const ang=i*Math.PI/5+(1-a)*.4;const x=effect.x+Math.cos(ang)*effect.radius*(1-a),y=effect.y+Math.sin(ang)*effect.radius*(1-a);g.fillStyle=i%2?'#fff6aa':'#ff8b38';g.beginPath();g.arc(x,y,3+3*a,0,Math.PI*2);g.fill();}g.restore();}else if(['frost-burst','poison-burst','heal-bloom','thorn-burst','leaf-lance','moss-impact'].includes(effect.kind)){drawAbilityEffect(effect);}else if(effect.kind==='base-danger'){continue;}else if(effect.kind==='merge'||effect.kind==='plant-death'){continue;}else{g.save();g.globalAlpha=a;label(effect.text,effect.x,effect.y-(1-a)*42,22+Math.sin((1-a)*Math.PI)*4,effect.poison?'#d98bff':effect.frost?'#a9eeff':effect.enemy?'#ffac91':'#fff2a1');g.restore();}}
