function bossPreview(stage){
 if(journeyBossCache.has(stage))return journeyBossCache.get(stage);
 const pending=(async()=>{
  const layout=stageOverrides[stage]||defaultStage(stage);
  await worldArt.ensure(layout);
  // Render with generous margins: live combat scale/weapon reach must not crop portraits.
  const portraitCanvas=document.createElement('canvas');portraitCanvas.width=640;portraitCanvas.height=640;
  const previous={context:g,stage:selectedStage,theme:previewStage,scene};
  try{
   g=portraitCanvas.getContext('2d');selectedStage=stage;previewStage=layout.theme;scene='home';
   drawBoss({kind:'boss',artId:'boss',x:320,y:520,phase:0,hit:0,recoil:0,flip:false,moving:false},170);
   const pixels=g.getImageData(0,0,640,640).data;
   let left=640,top=640,right=0,bottom=0,ink=0;
   for(let y=0;y<640;y++)for(let x=0;x<640;x++)if(pixels[(y*640+x)*4+3]>20){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y);ink+=pixels[(y*640+x)*4+3]/255;}
   if(right<left)throw new Error('Boss portrait is empty');
   const width=right-left+1,height=bottom-top+1,cx=(left+right)/2,cy=(top+bottom)/2;
   let radius=1;
   for(let y=top;y<=bottom;y++)for(let x=left;x<=right;x++)if(pixels[(y*640+x)*4+3]>20)radius=Math.max(radius,Math.hypot(x-cx,y-cy));
   // Equal visual mass, with a circular safety limit so long weapons stay inside the seal.
   // Optical exception: the Commander's bright hair and broad face read larger
   // than the Sultan's body despite comparable total ink. Journey portrait only.
   const opticalScale=layout.theme==='green'?.82:1;
   const scale=Math.min(Math.sqrt(23500/ink),118/radius)*opticalScale;
   const cropped=document.createElement('canvas');cropped.width=256;cropped.height=256;
   cropped.getContext('2d').drawImage(portraitCanvas,left,top,width,height,128-width*scale/2,128-height*scale/2,width*scale,height*scale);
   return {url:cropped.toDataURL('image/png'),name:bossNames[layout.theme]||bossNames.green};
  }finally{g=previous.context;selectedStage=previous.stage;previewStage=previous.theme;scene=previous.scene;}
 })().catch(error=>{journeyBossCache.delete(stage);throw error;});
 journeyBossCache.set(stage,pending);
 return pending;
}

