async function refreshPublishedStage(){if(stageEditor||refreshingStage)return;refreshingStage=true;try{const release=await readLiveRelease(true),next=release.stages;const backgroundsChanged=JSON.stringify(themeBackgrounds)!==JSON.stringify(release.settings.backgrounds||{});themeBackgrounds=release.settings.backgrounds||{};if(release.settings.growth)rigs.growth.config=validateGrowth(release.settings.growth);if(release.settings.motion)rigs.motion=validateMotions(release.settings.motion);if(release.settings.sizes&&JSON.stringify(release.settings.sizes)!==JSON.stringify(sizeConfig)){sizeConfig=validateSizes(release.settings.sizes);renderPlants();}liveVersions=release.versions;if(!backgroundsChanged&&JSON.stringify(next)===JSON.stringify(stageOverrides))return;stageOverrides=next;journeyMapCache.clear();journeyBossCache.clear();await worldArt.ensure(currentLayout());applyTheme();for(const enemy of enemies){enemy.path=null;enemy.navAge=0;}render();}catch{}finally{refreshingStage=false;}}
